        nodes.update(dep_list)

    remaining = {node: set(deps.get(node, [])) for node in nodes}
    out = []
    while remaining:
        ready = [n for n, d in remaining.items() if not d]
        if not ready:
            raise CycleError("dependency cycle detected")
        node = min(ready)
        out.append(node)
        del remaining[node]
        for d in remaining.values():
            d.discard(node)
    return out

